begin;
create table if not exists public.asb_access (user_id uuid primary key references auth.users(id) on delete cascade, employee_id uuid unique references public.employees(id), role text not null check(role in ('admin','employee')), enabled boolean not null default true);
insert into public.asb_access(user_id,role) select id,'admin' from auth.users where lower(email)='contact.asb13@gmail.com' on conflict do nothing;
do $$ begin if not exists(select 1 from public.asb_access where role='admin' and enabled) then raise exception 'Administrateur absent : vérifier email avant migration'; end if; end $$;
create or replace function public.asb_role() returns text language sql stable security definer set search_path='' as $$ select coalesce((select role from public.asb_access where user_id=auth.uid() and enabled),'none') $$;
create or replace function public.asb_employee() returns uuid language sql stable security definer set search_path='' as $$ select a.employee_id from public.asb_access a join public.employees e on e.id=a.employee_id where a.user_id=auth.uid() and a.enabled and a.role='employee' and coalesce(e.active,true) and not coalesce(e.archived,false) $$;
alter table public.employee_planning add column if not exists task_group uuid;
create table if not exists public.asb_tasks(id uuid primary key default gen_random_uuid(), task_group uuid not null, employee_id uuid references public.employees(id), label text not null check(length(trim(label))>0), done_at timestamptz, done_by uuid references public.employees(id));
-- Restrictive policy overrides historical permissive policies. Dedicated RPCs expose only selected fields to employees.
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t.tablename); execute format('drop policy if exists asb_v113_guard on public.%I',t.tablename); execute format('create policy asb_v113_guard on public.%I as restrictive for all to anon, authenticated using (public.asb_role() = ''admin'') with check (public.asb_role() = ''admin'')',t.tablename); end loop; end $$;
drop policy if exists asb_access_admin on public.asb_access;
create policy asb_access_admin on public.asb_access for all to authenticated using (public.asb_role()='admin') with check (public.asb_role()='admin');
drop policy if exists asb_tasks_admin on public.asb_tasks;
create policy asb_tasks_admin on public.asb_tasks for all to authenticated using (public.asb_role()='admin') with check (public.asb_role()='admin');
grant select,insert,update,delete on public.asb_access,public.asb_tasks to authenticated;
create or replace function public.asb_my_data() returns jsonb language sql stable security definer set search_path='' as $$
select jsonb_build_object('planning',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'project_id',p.project_id,'name',j.name,'address',j.address,'color',j.color,'title',p.title,'start_date',p.start_date,'end_date',p.end_date,'notes',p.notes,'task_group',p.task_group)) from public.employee_planning p join public.projects j on j.id=p.project_id where p.employee_id=public.asb_employee()),'[]'::jsonb),'tasks',coalesce((select jsonb_agg(t) from public.asb_tasks t where (t.employee_id is null or t.employee_id=public.asb_employee()) and exists(select 1 from public.employee_planning p where p.task_group=t.task_group and p.employee_id=public.asb_employee())),'[]'::jsonb),'materials',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'project_id',m.project_id,'content',m.content)) from public.project_materials m where exists(select 1 from public.employee_planning p where p.project_id=m.project_id and p.employee_id=public.asb_employee())),'[]'::jsonb)) $$;
create or replace function public.asb_check_task(task_id uuid, checked boolean) returns void language plpgsql security definer set search_path='' as $$ declare emp uuid:=public.asb_employee(); begin update public.asb_tasks t set done_at=case when checked then now() else null end,done_by=case when checked then emp else null end where t.id=task_id and emp is not null and (t.employee_id is null or t.employee_id=emp) and exists(select 1 from public.employee_planning p where p.task_group=t.task_group and p.employee_id=emp); if not found then raise exception 'Prestation non autorisée'; end if; end $$;
revoke all on function public.asb_my_data(),public.asb_check_task(uuid,boolean),public.asb_role(),public.asb_employee() from public;
grant execute on function public.asb_my_data(),public.asb_check_task(uuid,boolean),public.asb_role(),public.asb_employee() to authenticated,anon;
create or replace function public.asb_link_employee(account_email text, emp uuid) returns void language plpgsql security definer set search_path='' as $$ declare uid uuid; begin if public.asb_role()<>'admin' then raise exception 'Accès interdit'; end if; select id into uid from auth.users where lower(email)=lower(trim(account_email)); if uid is null then raise exception 'Compte Authentication introuvable'; end if; if exists(select 1 from public.asb_access where user_id=uid and role='admin') then raise exception 'Compte administrateur'; end if; insert into public.asb_access(user_id,employee_id,role) values(uid,emp,'employee') on conflict(user_id) do update set employee_id=excluded.employee_id,enabled=true; end $$;
revoke all on function public.asb_link_employee(text,uuid) from public;
grant execute on function public.asb_link_employee(text,uuid) to authenticated;
-- Restrict direct storage access; existing public bucket URLs remain public.
drop policy if exists asb_v113_storage_guard on storage.objects;
create policy asb_v113_storage_guard on storage.objects as restrictive for all to anon,authenticated using (public.asb_role()='admin') with check (public.asb_role()='admin');
commit;
